head.script:
scwin.checkVal = function() {
    return selectBox1.getText().replaceAll('&nbsp;', '') == '고구마';
}
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    //WebSquare.wUnit.addCommand('set', 'selectBox1.click();' );
    //WebSquare.wUnit.addCommand('pause', '500');
    //replaceAll을 이용해 치환하면 이전엔진결함도 success되어져서 자동화 보류
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.test_data = [{
        "col1": "&nbsp;고구마",
        "col2": "0002"
    }, {
        "col1": "nbsp;고구마",
        "col2": "0003"
    }, {
        "col1": "&nbsp&nbsp&nbsp고구마",
        "col2": "0004"
    }, {
        "col1": "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;고구마",
        "col2": "0005"
    }, {
        "col1": "&nbsp;고구마&nbsp",
        "col2": "0005"
    }];
    dc_c01.setJSON(test_data);
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
